const htmlContent = "<!DOCTYPE html>\n<html lang=\"fr\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Je note l'essentiel (Cours) - Géométrie de l'Espace & Volumes (Seconde Pro)</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brand: { 50: '#f0f9ff', 100: '#e0f2fe', 500: '#0ea5e9', 600: '#0284c7', 900: '#0c4a6e' }\n                    },\n                    fontFamily: {\n                        sans: ['Inter', 'sans-serif'],\n                        heading: ['Outfit', 'sans-serif'],\n                    }\n                }\n            }\n        }\n    </script>\n    <!-- Fonts & Icons -->\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    <!-- MathJax pour les formules LaTeX -->\n    <script>MathJax = { tex: { inlineMath: [['$', '$'], ['\\\\(', '\\\\)']] } };</script>\n    <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js\"></script>\n\n    <style>\n        body { font-family: 'Inter', sans-serif; background-color: #f8fafc; color: #1e293b; }\n        h1, h2, h3, h4, .font-heading { font-family: 'Outfit', sans-serif; }\n        .card-shadow { box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.05); }\n\n        @media print {\n            header, nav, .no-print { display: none !important; }\n            body { background-color: white; color: black; padding-bottom: 0 !important; }\n            .card-shadow { box-shadow: none; border: 1px solid #ccc; }\n        }\n    </style>\n\n    <!-- Three.js et OrbitControls pour la Simulation 3D Vraie -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js\"></script>\n\n</head>\n<body class=\"text-slate-800 bg-slate-50 min-h-screen pb-20\">\n\n    <!-- Header & Nav unifiée pour la Séquence Seconde -->\n    <header class=\"bg-slate-900 text-white sticky top-0 z-50 border-b border-slate-800 shadow-md\">\n        <div class=\"max-w-7xl mx-auto px-4 py-4 flex flex-col md:flex-row items-center justify-between gap-4\">\n            <div class=\"flex items-center gap-3\">\n                <div class=\"w-10 h-10 bg-sky-500/20 border border-sky-400/30 text-sky-400 rounded-xl flex items-center justify-center font-bold\">\n                    <i class=\"fa-solid fa-cube text-lg\"></i>\n                </div>\n                <div>\n                    <span class=\"text-xs font-bold tracking-widest uppercase text-sky-400\">Séquence Seconde Pro • Mathématiques</span>\n                    <h1 class=\"text-xl font-bold font-heading\">Géométrie de l'Espace & Volumes</h1>\n                </div>\n            </div>\n            <!-- Navigation de la Séquence -->\n            <nav class=\"flex flex-wrap items-center gap-1.5 text-xs font-bold\">\n                <a href=\"automatismes.html\" class=\"px-3 py-2 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors flex items-center gap-1.5\"><i class=\"fa-solid fa-bolt text-yellow-400\"></i> Automatismes</a>\n                <a href=\"activites.html\" class=\"px-3 py-2 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors flex items-center gap-1.5\"><i class=\"fa-solid fa-lightbulb text-emerald-400\"></i> Activités</a>\n                <a href=\"cours.html\" class=\"px-3 py-2 rounded-lg bg-sky-600 text-white font-extrabold shadow-sm flex items-center gap-1.5\"><i class=\"fa-solid fa-book-open\"></i> Cours</a>\n                <a href=\"td.html\" class=\"px-3 py-2 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors flex items-center gap-1.5\"><i class=\"fa-solid fa-dumbbell text-indigo-400\"></i> TD & Exercices</a>\n                <a href=\"tice.html\" class=\"px-3 py-2 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors flex items-center gap-1.5\"><i class=\"fa-solid fa-laptop-code text-purple-400\"></i> TP Numérique</a>\n                <a href=\"eval.html\" class=\"px-3 py-2 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors flex items-center gap-1.5\"><i class=\"fa-solid fa-graduation-cap text-red-400\"></i> Évaluation</a>\n            </nav>\n        </div>\n    </header>\n\n    <main class=\"max-w-5xl mx-auto px-4 py-8 space-y-12\">\n\n        <!-- ENTÊTE DE SÉQUENCE DE COURS CONFORME ÉDUCATION NATIONALE -->\n        <div class=\"bg-slate-900 text-white p-6 md:p-8 rounded-3xl shadow-xl border border-slate-800 space-y-4\">\n            <div class=\"flex flex-col md:flex-row items-start md:items-center justify-between gap-4\">\n                <div>\n                    <div class=\"flex items-center gap-2 mb-2\">\n                        <span class=\"bg-sky-500 text-slate-950 text-xs font-extrabold px-3 py-1 rounded-full uppercase tracking-wider\">Programme Officiel Seconde Pro</span>\n                        <span class=\"bg-slate-800 text-slate-300 text-xs font-semibold px-3 py-1 rounded-full border border-slate-700\">Module G1 : Géométrie de l'Espace & Volumes</span>\n                    </div>\n                    <h2 class=\"text-3xl font-extrabold font-heading text-white\">Fiche de Cours : Solides 3D, Surfaçage & Volumes</h2>\n                    <p class=\"text-sm text-slate-300 max-w-2xl\">Représentation en perspective cavalière, formules universelles des aires et volumes (prisme, cylindre, pyramide, cône, sphère), conversions d'unités ($m^3$, litres) et masse volumique.</p>\n                </div>\n\n                <button onclick=\"window.print()\" class=\"no-print bg-sky-500 hover:bg-sky-400 text-slate-950 font-bold text-xs px-5 py-3 rounded-xl shadow-md transition-colors flex items-center gap-2\">\n                    <i class=\"fa-solid fa-print\"></i> Imprimer le Cours PDF\n                </button>\n            </div>\n\n            <!-- SOMMAIRE COURS INTERACTIF -->\n            <div class=\"pt-4 border-t border-slate-800 grid grid-cols-2 md:grid-cols-5 gap-2 text-xs font-semibold\">\n                <a href=\"#partie1\" class=\"p-2 bg-slate-800 hover:bg-slate-700 text-sky-300 rounded-lg text-center transition-colors\">1. Perspective Cavalière</a>\n                <a href=\"#partie2\" class=\"p-2 bg-slate-800 hover:bg-slate-700 text-amber-300 rounded-lg text-center transition-colors\">2. Formules d'Aires 3D</a>\n                <a href=\"#partie3\" class=\"p-2 bg-slate-800 hover:bg-slate-700 text-purple-300 rounded-lg text-center transition-colors\">3. Formules des Volumes</a>\n                <a href=\"#partie4\" class=\"p-2 bg-slate-800 hover:bg-slate-700 text-emerald-300 rounded-lg text-center transition-colors\">4. Conversions & Masse</a>\n                <a href=\"#partie5\" class=\"p-2 bg-slate-800 hover:bg-slate-700 text-rose-300 rounded-lg text-center transition-colors\">5. Solides Composés Pro</a>\n            </div>\n        </div>\n\n        <!-- PARTIE 1 : PERSPECTIVE CAVALIÈRE ET SOLIDES -->\n        <section id=\"partie1\" class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <span class=\"w-10 h-10 bg-sky-100 text-sky-800 rounded-xl flex items-center justify-center font-bold text-lg\">1</span>\n                <div>\n                    <span class=\"text-xs font-bold text-sky-600 uppercase tracking-wider\">Partie 1 • Représentation dans le Plan</span>\n                    <h3 class=\"text-xl font-bold font-heading text-slate-900\">Règles de la Perspective Cavalière & Solides Usuels</h3>\n                </div>\n            </div>\n\n            <div class=\"space-y-4 text-xs text-slate-700 leading-relaxed\">\n                <!-- ENCADRÉ DÉFINITION 1 -->\n                <div class=\"bg-sky-50 border-l-4 border-sky-500 p-5 rounded-r-2xl space-y-2\">\n                    <h4 class=\"font-bold text-sky-900 text-sm flex items-center gap-2\">\n                        <i class=\"fa-solid fa-cube\"></i> Définition & Règles Canoniques de la Perspective Cavalière\n                    </h4>\n                    <p class=\"text-slate-800\">\n                        La <strong>perspective cavalière</strong> est une technique de dessin permettant de représenter un solide tridimensionnel sur une surface plane en 2D. <br>\n                        • <strong>La face avant :</strong> Dessinée en <strong>vraie grandeur</strong> (angles droits et longueurs conservés). <br>\n                        • <strong>Les arêtes fuyantes :</strong> Dessinées obliques (angle $\\alpha \\approx 30^\\circ$ à $45^\\circ$), réduites d'un rapport $k \\approx 0,5$, et <strong>strictement parallèles entre elles</strong>. <br>\n                        • <strong>Arêtes cachées :</strong> Représentées obligatoirement en <strong>traits pointillés rouges ou noirs</strong>.\n                    </p>\n                </div>\n\n                <!-- GALERIE DES 4 SCHÉMAS SVG DES SOLIDES DE RÉFÉRENCE -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6 pt-2\">\n                    <!-- SVG 1 : PAVÉ DROIT -->\n                    <div class=\"bg-slate-50 p-4 rounded-2xl border border-slate-200 text-center space-y-2\">\n                        <span class=\"font-bold text-sky-800 text-xs uppercase\">Figure 1. Pavé Droit (Parallélépipède)</span>\n                        <div class=\"py-2 bg-white rounded-xl border border-slate-200\">\n                            <svg width=\"280\" height=\"150\" viewBox=\"0 0 280 150\" class=\"mx-auto font-sans\">\n                                <rect x=\"50\" y=\"50\" width=\"120\" height=\"70\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"170\" y1=\"50\" x2=\"220\" y2=\"20\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"170\" y1=\"120\" x2=\"220\" y2=\"90\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"50\" y1=\"50\" x2=\"100\" y2=\"20\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"100\" y1=\"20\" x2=\"220\" y2=\"20\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"220\" y1=\"20\" x2=\"220\" y2=\"90\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n                                <line x1=\"50\" y1=\"120\" x2=\"100\" y2=\"90\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <line x1=\"100\" y1=\"20\" x2=\"100\" y2=\"90\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <line x1=\"100\" y1=\"90\" x2=\"220\" y2=\"90\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <text x=\"110\" y=\"138\" font-size=\"10\" font-weight=\"bold\" fill=\"#0284c7\" text-anchor=\"middle\">L</text>\n                                <text x=\"40\" y=\"85\" font-size=\"10\" font-weight=\"bold\" fill=\"#0284c7\" text-anchor=\"end\">h</text>\n                                <text x=\"200\" y=\"112\" font-size=\"10\" font-weight=\"bold\" fill=\"#ef4444\" text-anchor=\"middle\">l (fuyante)</text>\n                            </svg>\n                        </div>\n                    </div>\n\n                    <!-- SVG 2 : CYLINDRE DE RÉVOLUTION -->\n                    <div class=\"bg-slate-50 p-4 rounded-2xl border border-slate-200 text-center space-y-2\">\n                        <span class=\"font-bold text-emerald-800 text-xs uppercase\">Figure 2. Cylindre de Révolution</span>\n                        <div class=\"py-2 bg-white rounded-xl border border-slate-200\">\n                            <svg width=\"280\" height=\"150\" viewBox=\"0 0 280 150\" class=\"mx-auto font-sans\">\n                                <ellipse cx=\"140\" cy=\"30\" rx=\"70\" ry=\"18\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n                                <line x1=\"70\" y1=\"30\" x2=\"70\" y2=\"120\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n                                <line x1=\"210\" y1=\"30\" x2=\"210\" y2=\"120\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n                                <path d=\"M 70 120 A 70 18 0 0 0 210 120\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n                                <path d=\"M 70 120 A 70 18 0 0 1 210 120\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <line x1=\"140\" y1=\"30\" x2=\"210\" y2=\"30\" stroke=\"#059669\" stroke-width=\"1.5\" stroke-dasharray=\"2\"/>\n                                <text x=\"175\" y=\"24\" font-size=\"10\" font-weight=\"bold\" fill=\"#059669\" text-anchor=\"middle\">R</text>\n                                <text x=\"60\" y=\"75\" font-size=\"10\" font-weight=\"bold\" fill=\"#059669\" text-anchor=\"end\">h</text>\n                            </svg>\n                        </div>\n                    </div>\n\n                    <!-- SVG 3 : PYRAMIDE À BASE CARRÉE -->\n                    <div class=\"bg-slate-50 p-4 rounded-2xl border border-slate-200 text-center space-y-2\">\n                        <span class=\"font-bold text-amber-800 text-xs uppercase\">Figure 3. Pyramide à Base Carrée</span>\n                        <div class=\"py-2 bg-white rounded-xl border border-slate-200\">\n                            <svg width=\"280\" height=\"150\" viewBox=\"0 0 280 150\" class=\"mx-auto font-sans\">\n                                <polygon points=\"60,110 160,130 220,110 120,90\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"1.5\" stroke-dasharray=\"3\"/>\n                                <line x1=\"60\" y1=\"110\" x2=\"160\" y2=\"130\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n                                <line x1=\"160\" y1=\"130\" x2=\"220\" y2=\"110\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n                                <line x1=\"60\" y1=\"110\" x2=\"140\" y2=\"20\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n                                <line x1=\"160\" y1=\"130\" x2=\"140\" y2=\"20\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n                                <line x1=\"220\" y1=\"110\" x2=\"140\" y2=\"20\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n                                <line x1=\"120\" y1=\"90\" x2=\"140\" y2=\"20\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"110\" stroke=\"#7c3aed\" stroke-width=\"1.5\" stroke-dasharray=\"3\"/>\n                                <text x=\"148\" y=\"65\" font-size=\"10\" font-weight=\"bold\" fill=\"#7c3aed\">h</text>\n                            </svg>\n                        </div>\n                    </div>\n\n                    <!-- SVG 4 : CÔNE DE RÉVOLUTION -->\n                    <div class=\"bg-slate-50 p-4 rounded-2xl border border-slate-200 text-center space-y-2\">\n                        <span class=\"font-bold text-purple-800 text-xs uppercase\">Figure 4. Cône de Révolution</span>\n                        <div class=\"py-2 bg-white rounded-xl border border-slate-200\">\n                            <svg width=\"280\" height=\"150\" viewBox=\"0 0 280 150\" class=\"mx-auto font-sans\">\n                                <line x1=\"70\" y1=\"110\" x2=\"140\" y2=\"20\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                                <line x1=\"210\" y1=\"110\" x2=\"140\" y2=\"20\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                                <path d=\"M 70 110 A 70 18 0 0 0 210 110\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                                <path d=\"M 70 110 A 70 18 0 0 1 210 110\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                                <line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"110\" stroke=\"#7c3aed\" stroke-width=\"1.5\" stroke-dasharray=\"3\"/>\n                                <line x1=\"140\" y1=\"110\" x2=\"210\" y2=\"110\" stroke=\"#7c3aed\" stroke-width=\"1.5\" stroke-dasharray=\"3\"/>\n                                <text x=\"180\" y=\"60\" font-size=\"10\" font-weight=\"bold\" fill=\"#7c3aed\">Génératrice a</text>\n                                <text x=\"175\" y=\"123\" font-size=\"10\" font-weight=\"bold\" fill=\"#7c3aed\">R</text>\n                            </svg>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- PARTIE 2 : FORMULES D'AIRES LATÉRALES ET TOTALES ET SIMULATEUR INTERACTIF -->\n        <section id=\"partie2\" class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <span class=\"w-10 h-10 bg-amber-100 text-amber-800 rounded-xl flex items-center justify-center font-bold text-lg\">2</span>\n                <div>\n                    <span class=\"text-xs font-bold text-amber-600 uppercase tracking-wider\">Partie 2 • Surfaçage & Développements</span>\n                    <h3 class=\"text-xl font-bold font-heading text-slate-900\">Formules des Aires Latérales et Totales</h3>\n                </div>\n            </div>\n\n            <!-- CARTE DES FORMULES PAR CATEGORIE -->\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 text-xs\">\n                <!-- 1. CUBE ET PAVÉ -->\n                <div class=\"bg-slate-50 p-5 rounded-2xl border border-slate-200 space-y-3\">\n                    <span class=\"bg-sky-600 text-white font-extrabold text-[10px] uppercase px-2 py-0.5 rounded\">1. Pavé & Cube</span>\n                    <h4 class=\"font-bold text-slate-900 text-sm\">Surfaces Rectangulaires</h4>\n                    <ul class=\"space-y-1.5 text-slate-700 text-[11px]\">\n                        <li>• <strong>Cube :</strong> $A_{\\text{totale}} = 6 \\cdot a^2$</li>\n                        <li>• <strong>Pavé droit :</strong> $A_{\\text{totale}} = 2(L \\cdot l + L \\cdot h + l \\cdot h)$</li>\n                    </ul>\n                </div>\n\n                <!-- 2. CYLINDRE ET PRISME -->\n                <div class=\"bg-slate-50 p-5 rounded-2xl border border-slate-200 space-y-3\">\n                    <span class=\"bg-amber-600 text-white font-extrabold text-[10px] uppercase px-2 py-0.5 rounded\">2. Cylindre & Prisme</span>\n                    <h4 class=\"font-bold text-slate-900 text-sm\">Solides à Bases Égales</h4>\n                    <ul class=\"space-y-1.5 text-slate-700 text-[11px]\">\n                        <li>• <strong>Aire latérale Cylindre :</strong> $A_{\\text{lat}} = 2 \\pi R \\cdot h$</li>\n                        <li>• <strong>Aire totale Cylindre :</strong> $A_{\\text{tot}} = 2 \\pi R h + 2 \\pi R^2$</li>\n                        <li>• <strong>Aire latérale Prisme :</strong> $A_{\\text{lat}} = P_{\\text{base}} \\cdot h$</li>\n                    </ul>\n                </div>\n\n                <!-- 3. CÔNE ET SPHÈRE -->\n                <div class=\"bg-slate-50 p-5 rounded-2xl border border-slate-200 space-y-3\">\n                    <span class=\"bg-purple-600 text-white font-extrabold text-[10px] uppercase px-2 py-0.5 rounded\">3. Cône & Sphère</span>\n                    <h4 class=\"font-bold text-slate-900 text-sm\">Solides Ronds</h4>\n                    <ul class=\"space-y-1.5 text-slate-700 text-[11px]\">\n                        <li>• <strong>Aire latérale Cône :</strong> $A_{\\text{lat}} = \\pi R a$ <br> (où génératrice $a = \\sqrt{R^2 + h^2}$)</li>\n                        <li>• <strong>Aire Sphère :</strong> $A = 4 \\pi R^2$</li>\n                    </ul>\n                </div>\n            </div>\n\n            <!-- SIMULATEUR INTERACTIF DE PATRONS DE SOLIDES INSIDE PARTIE 2 -->\n            <div class=\"bg-slate-900 text-white p-6 md:p-8 rounded-3xl space-y-6 shadow-xl border border-slate-800 mt-6\">\n                <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-800 pb-4\">\n                    <div class=\"flex items-center gap-3\">\n                        <div class=\"w-10 h-10 bg-amber-500/20 border border-amber-400/30 text-amber-400 rounded-xl flex items-center justify-center font-bold text-lg shadow-inner\">\n                            <i class=\"fa-solid fa-cube text-amber-400\"></i>\n                        </div>\n                        <div>\n                            <span class=\"text-xs font-bold text-amber-400 uppercase tracking-widest flex items-center gap-1.5\">\n                                <span class=\"w-2 h-2 rounded-full bg-amber-400 animate-pulse\"></span>\n                                Outil Pédagogique Interactif 3D WebGL\n                            </span>\n                            <h4 class=\"text-xl font-bold font-heading text-white\">Simulateur de Pliage & Dépliage des Patrons (2D ↔ 3D)</h4>\n                        </div>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"bg-gradient-to-r from-amber-500 to-amber-600 text-slate-950 font-extrabold text-xs px-3.5 py-1.5 rounded-full uppercase tracking-wider shadow\">\n                            <i class=\"fa-solid fa-vr-cardboard mr-1\"></i> Mode 3D Temps Réel\n                        </span>\n                    </div>\n                </div>\n\n                <!-- Choix du Solide -->\n                <div class=\"grid grid-cols-2 sm:grid-cols-5 gap-2.5 text-xs font-bold\">\n                    <button onclick=\"selectSolid('cube')\" id=\"btn-cube\" class=\"p-3 bg-amber-500 text-slate-950 rounded-xl transition-all shadow-md flex flex-col items-center gap-1.5 hover:scale-[1.02]\">\n                        <i class=\"fa-solid fa-cube text-xl\"></i>\n                        <span>Cube / Pavé</span>\n                    </button>\n                    <button onclick=\"selectSolid('cylindre')\" id=\"btn-cylindre\" class=\"p-3 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all flex flex-col items-center gap-1.5 hover:scale-[1.02]\">\n                        <i class=\"fa-solid fa-bottle-water text-xl\"></i>\n                        <span>Cylindre</span>\n                    </button>\n                    <button onclick=\"selectSolid('pyramide')\" id=\"btn-pyramide\" class=\"p-3 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all flex flex-col items-center gap-1.5 hover:scale-[1.02]\">\n                        <i class=\"fa-solid fa-mountain text-xl\"></i>\n                        <span>Pyramide</span>\n                    </button>\n                    <button onclick=\"selectSolid('cone')\" id=\"btn-cone\" class=\"p-3 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all flex flex-col items-center gap-1.5 hover:scale-[1.02]\">\n                        <i class=\"fa-solid fa-traffic-cone text-xl\"></i>\n                        <span>Cône</span>\n                    </button>\n                    <button onclick=\"selectSolid('prisme')\" id=\"btn-prisme\" class=\"p-3 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all flex flex-col items-center gap-1.5 hover:scale-[1.02]\">\n                        <i class=\"fa-solid fa-shapes text-xl\"></i>\n                        <span>Prisme Droit</span>\n                    </button>\n                </div>\n\n                <!-- Zone de Simulation 3D Canvas + Contrôles -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 items-stretch pt-2\">\n                    \n                    <!-- Canvas 3D WebGL (Three.js) -->\n                    <div class=\"md:col-span-2 bg-slate-950 rounded-2xl border border-slate-800 relative overflow-hidden flex flex-col justify-between shadow-2xl min-h-[340px]\">\n                        \n                        <!-- Overlay Controls (Top Bar inside Canvas) -->\n                        <div class=\"absolute top-3 left-3 right-3 z-10 flex items-center justify-between pointer-events-none\">\n                            <span class=\"bg-slate-900/80 backdrop-blur-md text-amber-400 text-[10px] font-mono px-3 py-1.5 rounded-lg border border-slate-700/80 shadow flex items-center gap-1.5 pointer-events-auto\">\n                                <i class=\"fa-solid fa-arrows-spin text-amber-400 animate-spin-slow\"></i> \n                                <span>Glisser pour faire pivoter en 3D</span>\n                            </span>\n                            <div class=\"flex items-center gap-1.5 pointer-events-auto\">\n                                <button onclick=\"toggleViewMode()\" id=\"btn-view-mode\" class=\"px-2.5 py-1 bg-slate-800/90 hover:bg-slate-700 backdrop-blur text-slate-300 hover:text-white rounded-lg text-[11px] font-semibold border border-slate-700 transition flex items-center gap-1 shadow\">\n                                    <i class=\"fa-solid fa-eye text-sky-400\"></i>\n                                    <span id=\"view-mode-label\">Translucide</span>\n                                </button>\n                                <button onclick=\"reset3DCamera()\" class=\"px-2.5 py-1 bg-slate-800/90 hover:bg-slate-700 backdrop-blur text-slate-300 hover:text-white rounded-lg text-[11px] font-semibold border border-slate-700 transition shadow\" title=\"Réinitialiser la vue 3D\">\n                                    <i class=\"fa-solid fa-rotate-left\"></i>\n                                </button>\n                            </div>\n                        </div>\n\n                        <!-- WebGL 3D Container -->\n                        <div id=\"patron-3d-canvas-container\" class=\"w-full h-[340px] cursor-grab active:cursor-grabbing\">\n                            <!-- Three.js Canvas Injecté ici -->\n                        </div>\n\n                        <!-- Legend & Status Footer inside Canvas -->\n                        <div class=\"bg-slate-900/90 backdrop-blur-md px-4 py-2 border-t border-slate-800/80 flex items-center justify-between text-[11px] font-mono text-slate-400\">\n                            <div id=\"patron-legend\" class=\"truncate pr-2\">\n                                Patron du Cube : 6 faces carrées égales.\n                            </div>\n                            <button onclick=\"togglePlayAnimation()\" id=\"btn-play-anim\" class=\"px-3 py-1 bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold rounded-md transition flex items-center gap-1.5 shadow text-[10px]\">\n                                <i class=\"fa-solid fa-play\" id=\"play-icon\"></i>\n                                <span id=\"play-text\">Animer</span>\n                            </button>\n                        </div>\n                    </div>\n\n                    <!-- Panneau de Réglage & Formules en Temps Réel -->\n                    <div class=\"bg-slate-800/90 backdrop-blur p-5 rounded-2xl border border-slate-700 space-y-4 text-xs flex flex-col justify-between shadow-xl\">\n                        <div class=\"space-y-3\">\n                            <div>\n                                <div class=\"flex items-center justify-between mb-1.5\">\n                                    <label class=\"font-bold text-amber-400 flex items-center gap-1.5\">\n                                        <i class=\"fa-solid fa-sliders\"></i>\n                                        <span>Niveau de Pliage :</span>\n                                    </label>\n                                    <span id=\"fold-val\" class=\"font-mono font-bold text-white bg-slate-900 px-2 py-0.5 rounded border border-slate-700 text-[11px]\">0 % (À plat 2D)</span>\n                                </div>\n                                <input type=\"range\" id=\"fold-range\" min=\"0\" max=\"100\" value=\"0\" step=\"0.5\" oninput=\"updatePatronSim()\" class=\"w-full accent-amber-400 cursor-pointer h-2 bg-slate-900 rounded-lg appearance-none\">\n                                <div class=\"flex justify-between text-[10px] font-mono text-slate-400 mt-1\">\n                                    <span>Patron 2D (0%)</span>\n                                    <span>Pliage (50%)</span>\n                                    <span>Solide 3D (100%)</span>\n                                </div>\n                            </div>\n\n                            <div class=\"space-y-2 border-t border-slate-700/80 pt-3\">\n                                <div class=\"flex justify-between items-center text-slate-300 font-mono bg-slate-900/60 px-3 py-2 rounded-xl border border-slate-700/50\">\n                                    <span class=\"text-slate-400\">Aire Latérale $A_{\\text{lat}}$ :</span>\n                                    <span id=\"calc-alat\" class=\"font-bold text-amber-300 text-sm\">--</span>\n                                </div>\n                                <div class=\"flex justify-between items-center text-slate-300 font-mono bg-slate-900/60 px-3 py-2 rounded-xl border border-slate-700/50\">\n                                    <span class=\"text-slate-400\">Aire Totale $A_{\\text{tot}}$ :</span>\n                                    <span id=\"calc-atot\" class=\"font-bold text-emerald-400 text-sm\">--</span>\n                                </div>\n                                <div class=\"flex justify-between items-center text-slate-300 font-mono bg-slate-900/60 px-3 py-2 rounded-xl border border-slate-700/50\">\n                                    <span class=\"text-slate-400\">Volume $V$ :</span>\n                                    <span id=\"calc-vol\" class=\"font-bold text-sky-400 text-sm\">--</span>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div id=\"patron-formula-box\" class=\"p-3.5 bg-slate-900/90 rounded-xl border border-slate-700 text-[11px] text-slate-300 font-mono leading-relaxed shadow-inner\">\n                            Formule patron : $A_{\\text{tot}} = 6 \\times a^2$\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </section>\n\n        <!-- PARTIE 3 : FORMULES UNIVERSELLES DES VOLUMES -->\n        <section id=\"partie3\" class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <span class=\"w-10 h-10 bg-purple-100 text-purple-800 rounded-xl flex items-center justify-center font-bold text-lg\">3</span>\n                <div>\n                    <span class=\"text-xs font-bold text-purple-600 uppercase tracking-wider\">Partie 3 • Calculs d'Espace</span>\n                    <h3 class=\"text-xl font-bold font-heading text-slate-900\">Formules Universelles des Volumes $V$</h3>\n                </div>\n            </div>\n\n            <div class=\"space-y-4 text-xs text-slate-700 leading-relaxed\">\n                <!-- REGLE UNIVERSELLE DES VOLUMES -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n                    <div class=\"p-5 bg-emerald-50 border-l-4 border-emerald-500 rounded-r-2xl space-y-2\">\n                        <h4 class=\"font-bold text-emerald-900 text-sm flex items-center gap-2\">\n                            <i class=\"fa-solid fa-shapes\"></i> 1. Solides Dégagés (Bases Parallèles Égales)\n                        </h4>\n                        <p class=\"text-slate-800 font-mono text-sm\">$\\mathbf{V = B \\times h}$</p>\n                        <p class=\"text-slate-700 text-[11px]\">\n                            • <strong>Cube :</strong> $V = a^3$ <br>\n                            • <strong>Pavé droit :</strong> $V = L \\times l \\times h$ <br>\n                            • <strong>Cylindre de révolution :</strong> $V = \\pi R^2 h$ <br>\n                            • <strong>Prisme droit :</strong> $V = A_{\\text{base}} \\times h$\n                        </p>\n                    </div>\n\n                    <div class=\"p-5 bg-rose-50 border-l-4 border-rose-500 rounded-r-2xl space-y-2\">\n                        <h4 class=\"font-bold text-rose-900 text-sm flex items-center gap-2\">\n                            <i class=\"fa-solid fa-caret-up\"></i> 2. Solides à Pointe (Apex)\n                        </h4>\n                        <p class=\"text-slate-800 font-mono text-sm\">$\\mathbf{V = \\frac{1}{3} \\times B \\times h}$</p>\n                        <p class=\"text-slate-700 text-[11px]\">\n                            • <strong>Pyramide :</strong> $V = \\frac{1}{3} A_{\\text{base}} \\times h$ <br>\n                            • <strong>Cône de révolution :</strong> $V = \\frac{1}{3} \\pi R^2 h$\n                        </p>\n                    </div>\n                </div>\n\n                <!-- BOULE / SPHERE -->\n                <div class=\"p-5 bg-indigo-50 border border-indigo-200 rounded-2xl space-y-2\">\n                    <h4 class=\"font-bold text-indigo-950 text-sm flex items-center gap-2\">\n                        <i class=\"fa-solid fa-globe\"></i> 3. Boule / Sphère\n                    </h4>\n                    <p class=\"text-indigo-900 font-mono text-sm\">$\\mathbf{V = \\frac{4}{3} \\pi R^3}$</p>\n                    <p class=\"text-slate-700 text-[11px]\">Remarque : La moitié d'une boule (demi-sphère) a un volume $V = \\frac{2}{3} \\pi R^3$.</p>\n                </div>\n            </div>\n        </section>\n\n        <!-- PARTIE 4 : CONVERSIONS ET MASSE VOLUMIQUE -->\n        <section id=\"partie4\" class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <span class=\"w-10 h-10 bg-emerald-100 text-emerald-800 rounded-xl flex items-center justify-center font-bold text-lg\">4</span>\n                <div>\n                    <span class=\"text-xs font-bold text-emerald-600 uppercase tracking-wider\">Partie 4 • Unités & Masse Volumique</span>\n                    <h3 class=\"text-xl font-bold font-heading text-slate-900\">Conversions Volume - Litres & Calcul de Masse</h3>\n                </div>\n            </div>\n\n            <div class=\"space-y-4 text-xs text-slate-700 leading-relaxed\">\n                <!-- EQUIVALENCES FONDAMENTALES -->\n                <div class=\"bg-emerald-50 border-2 border-emerald-300 p-5 rounded-2xl space-y-3\">\n                    <h4 class=\"font-bold text-emerald-950 text-sm flex items-center gap-2\">\n                        <i class=\"fa-solid fa-droplet text-emerald-600\"></i> Équivalences Fondamentales à Mémoriser Absolument !\n                    </h4>\n                    <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-center font-mono font-bold text-slate-900\">\n                        <div class=\"p-3 bg-white rounded-xl border border-emerald-200\">\n                            $1 \\text{ dm}^3 = 1 \\text{ Litre (L)}$\n                        </div>\n                        <div class=\"p-3 bg-white rounded-xl border border-emerald-200\">\n                            $1 \\text{ m}^3 = 1\\,000 \\text{ L} = 1 \\text{ kL}$\n                        </div>\n                        <div class=\"p-3 bg-white rounded-xl border border-emerald-200\">\n                            $1 \\text{ cm}^3 = 1 \\text{ mL}$\n                        </div>\n                    </div>\n                </div>\n\n                <!-- MASSE VOLUMIQUE -->\n                <div class=\"p-5 bg-slate-50 border border-slate-200 rounded-2xl space-y-2\">\n                    <h4 class=\"font-bold text-slate-900 text-sm flex items-center gap-2\">\n                        <i class=\"fa-solid fa-weight-hanging text-sky-600\"></i> Relation entre Volume et Masse : $m = \\rho \\times V$\n                    </h4>\n                    <p class=\"text-slate-700\">\n                        La <strong>masse volumique</strong> $\\rho$ (en $\\text{kg/dm}^3$ ou $\\text{g/cm}^3$) permet de calculer la masse $m$ d'un corps à partir de son volume $V$ : <br>\n                        $\\mathbf{m = \\rho \\times V} \\qquad \\text{et} \\qquad \\mathbf{V = \\frac{m}{\\rho}}$ <br>\n                        <em>Exemple : L'acier a une masse volumique $\\rho = 7,85 \\text{ kg/dm}^3$. Un volume de $10 \\text{ dm}^3$ d'acier a donc une masse $m = 7,85 \\times 10 = \\mathbf{78,5 \\text{ kg}}$.</em>\n                    </p>\n                </div>\n            </div>\n        </section>\n\n        <!-- PARTIE 5 : SOLIDES COMPOSÉS PRO -->\n        <section id=\"partie5\" class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <span class=\"w-10 h-10 bg-rose-100 text-rose-800 rounded-xl flex items-center justify-center font-bold text-lg\">5</span>\n                <div>\n                    <span class=\"text-xs font-bold text-rose-600 uppercase tracking-wider\">Partie 5 • Application Industrielle</span>\n                    <h3 class=\"text-xl font-bold font-heading text-slate-900\">Méthode de Calcul des Solides Composés & Percés</h3>\n                </div>\n            </div>\n\n            <div class=\"bg-slate-900 text-white p-6 rounded-2xl space-y-4 text-xs shadow-lg border border-slate-800\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"bg-emerald-500 text-slate-950 font-extrabold text-[10px] uppercase px-3 py-1 rounded-full\">Cas Concret Chaudronnerie & Cuves</span>\n                    <span class=\"text-slate-400 text-xs font-medium\">MP3D / TCI / REMI</span>\n                </div>\n\n                <h4 class=\"text-base font-bold font-heading text-emerald-400\">Calcul du Volume d'un Réservoir Sous Pression (Cylindre + 2 Demi-Sphères)</h4>\n                <p class=\"text-slate-300 leading-relaxed\">\n                    Un réservoir industriel est composé d'une partie centrale cylindrique de rayon $R = 0,5 \\text{ m}$ et de longueur $h = 2 \\text{ m}$, fermée à chaque extrémité par une demi-sphère de rayon $R = 0,5 \\text{ m}$. <br>\n                    <em>1. Déterminer le volume total du réservoir. <br>\n                    2. Exprimer sa capacité en Litres.</em>\n                </p>\n\n                <div class=\"bg-slate-800 p-4 rounded-xl border border-slate-700 space-y-2 font-mono text-slate-200\">\n                    <p><strong class=\"text-sky-400\">Étape 1 : Volume du Cylindre :</strong> $V_{\\text{cyl}} = \\pi \\times 0,5^2 \\times 2 = 0,5 \\pi \\approx \\mathbf{1,5708 \\text{ m}^3}$.</p>\n                    <p><strong class=\"text-sky-400\">Étape 2 : Volume des 2 Demi-sphères (= 1 Sphère entière) :</strong> $V_{\\text{sph}} = \\frac{4}{3} \\pi \\times 0,5^3 \\approx \\mathbf{0,5236 \\text{ m}^3}$.</p>\n                    <p><strong class=\"text-emerald-400\">Étape 3 : Volume Total & Capacité :</strong> $V_{\\text{tot}} = 1,5708 + 0,5236 = \\mathbf{2,0944 \\text{ m}^3} = \\mathbf{2\\,094,4 \\text{ Litres}}$.</p>\n                </div>\n            </div>\n        </section>\n\n        <!-- AUTO-ÉVALUATION INTERACTIVE EN FIN DE COURS -->\n        <section class=\"bg-white p-6 md:p-8 rounded-3xl border border-slate-200 card-shadow space-y-6\">\n            <div class=\"flex items-center gap-3 border-b border-slate-100 pb-4\">\n                <div class=\"w-10 h-10 bg-sky-100 text-sky-600 rounded-xl flex items-center justify-center font-bold\">\n                    <i class=\"fa-solid fa-check-double text-lg\"></i>\n                </div>\n                <div>\n                    <h3 class=\"text-xl font-bold text-slate-900\">Auto-Évaluation Express (Testez vos réflexes)</h3>\n                    <p class=\"text-xs text-slate-500 font-medium\">Vérification immédiate des connaissances sur les volumes</p>\n                </div>\n            </div>\n\n            <div class=\"space-y-4 text-xs\">\n                <!-- Q1 -->\n                <div class=\"p-4 bg-slate-50 rounded-xl border border-slate-200 space-y-2\">\n                    <p class=\"font-bold text-slate-900\">Question 1 : Combien de Litres contient un volume de $2,5 \\text{ m}^3$ ?</p>\n                    <div class=\"flex flex-wrap gap-2\">\n                        <button onclick=\"alert('✅ Bravo ! 1 m^3 = 1000 L donc 2.5 m^3 = 2500 L.')\" class=\"px-3 py-1.5 bg-white border border-slate-300 rounded-lg hover:bg-slate-100\">A) 2 500 Litres</button>\n                        <button onclick=\"alert('❌ Faux. 1 m^3 vaut 1000 dm^3 (Litres).')\" class=\"px-3 py-1.5 bg-white border border-slate-300 rounded-lg hover:bg-slate-100\">B) 250 Litres</button>\n                    </div>\n                </div>\n\n                <!-- Q2 -->\n                <div class=\"p-4 bg-slate-50 rounded-xl border border-slate-200 space-y-2\">\n                    <p class=\"font-bold text-slate-900\">Question 2 : Quelle est la formule du volume d'un cône de révolution ?</p>\n                    <div class=\"flex flex-wrap gap-2\">\n                        <button onclick=\"alert('✅ Bravo ! V = (1/3) * pi * R^2 * h.')\" class=\"px-3 py-1.5 bg-white border border-slate-300 rounded-lg hover:bg-slate-100\">A) V = (1/3) * π * R² * h</button>\n                        <button onclick=\"alert('❌ Faux. Ça c'est le volume du cylindre !')\" class=\"px-3 py-1.5 bg-white border border-slate-300 rounded-lg hover:bg-slate-100\">B) V = π * R² * h</button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n    </main>\n\n    <!-- SCRIPT DU SIMULATEUR 3D WEBGL (THREE.JS) -->\n    <script>\n        let scene, camera, renderer, controls;\n        let solidGroup = null;\n        let currentSolid = 'cube';\n        let isPlaying = false;\n        let playDirection = 1;\n        let animFrameId = null;\n        let viewMode = 'transp'; // 'solid', 'transp', 'wire'\n\n                const SOLIDS_CONFIG = {\n            cube: {\n                name: \"Cube / Pavé\",\n                legend: \"Patron du Cube : 6 faces carrées identiques ($A = 6 \\times a^2$). Pliage exact à 90°.\",\n                formula: \"<strong>Cube (a = 4 cm) :</strong><br>• $A_{\\\\text{lat}} = 4 \\times a^2 = 64 \\text{ cm}^2$<br>• $A_{\\\\text{tot}} = 6 \\times a^2 = 96 \\text{ cm}^2$<br>• $V = a^3 = 64 \\text{ cm}^3$\",\n                calc: { alat: \"64 cm²\", atot: \"96 cm²\", vol: \"64 cm³\" }\n            },\n            cylindre: {\n                name: \"Cylindre de Révolution\",\n                legend: \"Patron du Cylindre : Rectangle latéral ($2\\pi R \\times h$) qui s'enroule + 2 disques de base.\",\n                formula: \"<strong>Cylindre (R = 3 cm, h = 6 cm) :</strong><br>• $A_{\\\\text{lat}} = 2\\pi R h \\approx 113{,}1 \\text{ cm}^2$<br>• $A_{\\\\text{tot}} = A_{\\\\text{lat}} + 2\\pi R^2 \\approx 169{,}6 \\text{ cm}^2$<br>• $V = \\pi R^2 h \\approx 169{,}6 \\text{ cm}^3$\",\n                calc: { alat: \"113,1 cm²\", atot: \"169,6 cm²\", vol: \"169,6 cm³\" }\n            },\n            pyramide: {\n                name: \"Pyramide à base carrée\",\n                legend: \"Patron de la Pyramide : Base carrée + 4 triangles isocèles se rejoignant au sommet (apex).\",\n                formula: \"<strong>Pyramide (a = 5 cm, h = 6 cm) :</strong><br>• $A_{\\\\text{lat}} = 4 \\times \\frac{a \\times h_t}{2} = 65 \\text{ cm}^2$<br>• $A_{\\\\text{tot}} = a^2 + A_{\\\\text{lat}} = 90 \\text{ cm}^2$<br>• $V = \\frac{1}{3} a^2 h = 50 \\text{ cm}^3$\",\n                calc: { alat: \"65 cm²\", atot: \"90 cm²\", vol: \"50 cm³\" }\n            },\n            cone: {\n                name: \"Cône de Révolution\",\n                legend: \"Patron du Cône : Secteur circulaire (génératrice a) s'enroulant + disque de base (rayon R).\",\n                formula: \"<strong>Cône (R = 3 cm, a = 7 cm, h = 6,3 cm) :</strong><br>• $A_{\\\\text{lat}} = \\pi R a \\approx 66{,}0 \\text{ cm}^2$<br>• $A_{\\\\text{tot}} = A_{\\\\text{lat}} + \\pi R^2 \\approx 94{,}2 \\text{ cm}^2$<br>• $V = \\frac{1}{3}\\pi R^2 h \\approx 59{,}4 \\text{ cm}^3$\",\n                calc: { alat: \"66,0 cm²\", atot: \"94,2 cm²\", vol: \"59,4 cm³\" }\n            },\n            prisme: {\n                name: \"Prisme Droit Triangulaire\",\n                legend: \"Patron du Prisme Droit : 3 rectangles latéraux + 2 bases triangulaires articulées.\",\n                formula: \"<strong>Prisme Triangulaire (b = 4 cm, ht = 3,5 cm, h = 6 cm) :</strong><br>• $A_{\\\\text{lat}} = P_{\\\\text{base}} \\times h = 72 \\text{ cm}^2$<br>• $A_{\\\\text{tot}} = A_{\\\\text{lat}} + 2 A_{\\\\text{base}} = 86 \\text{ cm}^2$<br>• $V = A_{\\\\text{base}} \\times h = 42 \\text{ cm}^3$\",\n                calc: { alat: \"72 cm²\", atot: \"86 cm²\", vol: \"42 cm³\" }\n            }\n        };\n\n        function selectSolid(solid) {\n            currentSolid = solid;\n            ['cube', 'cylindre', 'pyramide', 'cone', 'prisme'].forEach(s => {\n                const btn = document.getElementById('btn-' + s);\n                if (btn) {\n                    if (s === solid) {\n                        btn.className = 'p-3 bg-amber-500 text-slate-950 rounded-xl transition-all shadow-md flex flex-col items-center gap-1.5 font-bold hover:scale-[1.02]';\n                    } else {\n                        btn.className = 'p-3 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all flex flex-col items-center gap-1.5 font-bold hover:scale-[1.02]';\n                    }\n                }\n            });\n            updatePatronSim();\n        }\n\n        function togglePlayAnimation() {\n            isPlaying = !isPlaying;\n            const playText = document.getElementById('play-text');\n            const playIcon = document.getElementById('play-icon');\n            const playBtn = document.getElementById('btn-play-anim');\n            if (isPlaying) {\n                if (playText) playText.innerText = 'Pause';\n                if (playIcon) playIcon.className = 'fa-solid fa-pause';\n                if (playBtn) playBtn.className = 'px-3 py-1 bg-amber-400 text-slate-950 font-bold rounded-md transition flex items-center gap-1.5 shadow text-[10px] animate-pulse';\n            } else {\n                if (playText) playText.innerText = 'Animer';\n                if (playIcon) playIcon.className = 'fa-solid fa-play';\n                if (playBtn) playBtn.className = 'px-3 py-1 bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold rounded-md transition flex items-center gap-1.5 shadow text-[10px]';\n            }\n        }\n\n        function toggleViewMode() {\n            const modes = ['transp', 'solid', 'wire'];\n            const labels = { transp: 'Translucide', solid: 'Solide Opac', wire: 'Fil de fer' };\n            const idx = (modes.indexOf(viewMode) + 1) % modes.length;\n            viewMode = modes[idx];\n            const labelEl = document.getElementById('view-mode-label');\n            if (labelEl) labelEl.innerText = labels[viewMode];\n            updatePatronSim();\n        }\n\n        function reset3DCamera() {\n            if (camera && controls) {\n                camera.position.set(0, 3.2, 6.0);\n                controls.target.set(0, 1.0, 0);\n                controls.update();\n            }\n        }\n\n        function init3D() {\n            const container = document.getElementById('patron-3d-canvas-container');\n            if (!container) return;\n            container.innerHTML = '';\n\n            const width = container.clientWidth || 500;\n            const height = 340;\n\n            scene = new THREE.Scene();\n            scene.background = new THREE.Color(0x040711);\n\n            camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);\n            camera.position.set(0, 3.2, 6.0);\n\n            renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });\n            renderer.setSize(width, height);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            container.appendChild(renderer.domElement);\n\n            if (typeof THREE.OrbitControls !== 'undefined') {\n                controls = new THREE.OrbitControls(camera, renderer.domElement);\n                controls.enableDamping = true;\n                controls.dampingFactor = 0.08;\n                controls.target.set(0, 1.0, 0);\n                controls.maxPolarAngle = Math.PI / 2 + 0.15;\n            }\n\n            const ambient = new THREE.AmbientLight(0xffffff, 0.85);\n            scene.add(ambient);\n\n            const sun = new THREE.DirectionalLight(0xffffff, 0.95);\n            sun.position.set(6, 12, 8);\n            scene.add(sun);\n\n            const cyanLight = new THREE.DirectionalLight(0x38bdf8, 0.5);\n            cyanLight.position.set(-6, -4, -6);\n            scene.add(cyanLight);\n\n            const grid = new THREE.GridHelper(14, 14, 0x334155, 0x1e293b);\n            grid.position.y = -0.01;\n            scene.add(grid);\n\n            window.addEventListener('resize', () => {\n                if (!container || !renderer || !camera) return;\n                const w = container.clientWidth;\n                const h = 340;\n                camera.aspect = w / h;\n                camera.updateProjectionMatrix();\n                renderer.setSize(w, h);\n            });\n\n            updatePatronSim();\n            animate3D();\n        }\n\n        function animate3D() {\n            animFrameId = requestAnimationFrame(animate3D);\n            if (controls) controls.update();\n\n            if (isPlaying) {\n                const slider = document.getElementById('fold-range');\n                if (slider) {\n                    let val = parseFloat(slider.value) + playDirection * 0.7;\n                    if (val >= 100) { val = 100; playDirection = -1; }\n                    if (val <= 0) { val = 0; playDirection = 1; }\n                    slider.value = val;\n                    updatePatronSim();\n                }\n            }\n\n            if (renderer && scene && camera) {\n                renderer.render(scene, camera);\n            }\n        }\n\n        function getMaterial(colorHex, isBase = false) {\n            const color = new THREE.Color(colorHex);\n            if (viewMode === 'wire') {\n                return new THREE.MeshBasicMaterial({ color: color, wireframe: true });\n            } else if (viewMode === 'transp') {\n                return new THREE.MeshStandardMaterial({\n                    color: color,\n                    roughness: 0.2,\n                    metalness: 0.1,\n                    transparent: true,\n                    opacity: 0.75,\n                    side: THREE.DoubleSide\n                });\n            } else {\n                return new THREE.MeshStandardMaterial({\n                    color: color,\n                    roughness: 0.35,\n                    metalness: 0.15,\n                    side: THREE.DoubleSide\n                });\n            }\n        }\n\n        function addOutline(mesh, colorHex = 0xffffff) {\n            const edges = new THREE.EdgesGeometry(mesh.geometry);\n            const lineMat = new THREE.LineBasicMaterial({ color: colorHex, linewidth: 1.5 });\n            const line = new THREE.LineSegments(edges, lineMat);\n            mesh.add(line);\n        }\n\n        function updatePatronSim() {\n            const foldRange = document.getElementById('fold-range');\n            if (!foldRange) return;\n\n            const fold = parseFloat(foldRange.value);\n            const foldProgress = fold / 100;\n\n            const foldValLabel = document.getElementById('fold-val');\n            if (foldValLabel) {\n                if (fold === 0) foldValLabel.innerText = '0 % (Patron 2D à plat)';\n                else if (fold === 100) foldValLabel.innerText = '100 % (Solide 3D fermé)';\n                else foldValLabel.innerText = Math.round(fold) + ' % (Pliage 3D)';\n            }\n\n            const cfg = SOLIDS_CONFIG[currentSolid] || SOLIDS_CONFIG.cube;\n\n            const alatEl = document.getElementById('calc-alat');\n            const atotEl = document.getElementById('calc-atot');\n            const volEl = document.getElementById('calc-vol');\n            const formulaBox = document.getElementById('patron-formula-box');\n            const legend = document.getElementById('patron-legend');\n\n            if (alatEl) alatEl.innerText = cfg.calc.alat;\n            if (atotEl) atotEl.innerText = cfg.calc.atot;\n            if (volEl) volEl.innerText = cfg.calc.vol;\n            if (formulaBox) formulaBox.innerHTML = cfg.formula;\n            if (legend) legend.innerHTML = cfg.legend;\n\n            if (window.MathJax && MathJax.typesetPromise) {\n                MathJax.typesetPromise([formulaBox, legend]).catch(() => {});\n            }\n\n            if (!scene) return;\n\n            if (solidGroup) {\n                scene.remove(solidGroup);\n                solidGroup.traverse(child => {\n                    if (child.geometry) child.geometry.dispose();\n                    if (child.material) {\n                        if (Array.isArray(child.material)) child.material.forEach(m => m.dispose());\n                        else child.material.dispose();\n                    }\n                });\n            }\n\n            if (currentSolid === 'cube') {\n                buildCube3D(foldProgress);\n            } else if (currentSolid === 'pyramide') {\n                buildPyramid3D(foldProgress);\n            } else if (currentSolid === 'prisme') {\n                buildPrism3D(foldProgress);\n            } else if (currentSolid === 'cylindre') {\n                buildCylinder3D(foldProgress);\n            } else if (currentSolid === 'cone') {\n                buildCone3D(foldProgress);\n            }\n        }\n\n        // ==========================================\n        // 1. CUBE / PAVÉ (Fermeture 3D exacte)\n        // ==========================================\n        function buildCube3D(fp) {\n            solidGroup = new THREE.Group();\n            const s = 1.8;\n            const fa = fp * (Math.PI / 2);\n\n            const baseMat = getMaterial(0x0284c7, true);\n            const sideMat = getMaterial(0xf59e0b);\n            const topMat  = getMaterial(0x10b981);\n\n            // Base au sol\n            const baseGeo = new THREE.PlaneGeometry(s, s);\n            baseGeo.rotateX(-Math.PI / 2);\n            const baseMesh = new THREE.Mesh(baseGeo, baseMat);\n            addOutline(baseMesh, 0x38bdf8);\n            solidGroup.add(baseMesh);\n\n            // Face Nord\n            const nHinge = new THREE.Group();\n            nHinge.position.set(0, 0, -s/2);\n            nHinge.rotation.x = -fa;\n            const nGeo = new THREE.PlaneGeometry(s, s);\n            nGeo.rotateX(-Math.PI / 2);\n            nGeo.translate(0, 0, -s/2);\n            const nMesh = new THREE.Mesh(nGeo, sideMat);\n            addOutline(nMesh, 0xfcd34d);\n            nHinge.add(nMesh);\n            solidGroup.add(nHinge);\n\n            // Face Sud\n            const sHinge = new THREE.Group();\n            sHinge.position.set(0, 0, s/2);\n            sHinge.rotation.x = fa;\n            const sGeo = new THREE.PlaneGeometry(s, s);\n            sGeo.rotateX(-Math.PI / 2);\n            sGeo.translate(0, 0, s/2);\n            const sMesh = new THREE.Mesh(sGeo, sideMat);\n            addOutline(sMesh, 0xfcd34d);\n            sHinge.add(sMesh);\n            solidGroup.add(sHinge);\n\n            // Face Ouest\n            const wHinge = new THREE.Group();\n            wHinge.position.set(-s/2, 0, 0);\n            wHinge.rotation.z = fa;\n            const wGeo = new THREE.PlaneGeometry(s, s);\n            wGeo.rotateX(-Math.PI / 2);\n            wGeo.translate(-s/2, 0, 0);\n            const wMesh = new THREE.Mesh(wGeo, sideMat);\n            addOutline(wMesh, 0xfcd34d);\n            wHinge.add(wMesh);\n            solidGroup.add(wHinge);\n\n            // Face Est\n            const eHinge = new THREE.Group();\n            eHinge.position.set(s/2, 0, 0);\n            eHinge.rotation.z = -fa;\n            const eGeo = new THREE.PlaneGeometry(s, s);\n            eGeo.rotateX(-Math.PI / 2);\n            eGeo.translate(s/2, 0, 0);\n            const eMesh = new THREE.Mesh(eGeo, sideMat);\n            addOutline(eMesh, 0xfcd34d);\n            eHinge.add(eMesh);\n            solidGroup.add(eHinge);\n\n            // Couvercle\n            const tHinge = new THREE.Group();\n            tHinge.position.set(s, 0, 0);\n            tHinge.rotation.z = -fa;\n            const tGeo = new THREE.PlaneGeometry(s, s);\n            tGeo.rotateX(-Math.PI / 2);\n            tGeo.translate(s/2, 0, 0);\n            const tMesh = new THREE.Mesh(tGeo, topMat);\n            addOutline(tMesh, 0x6ee7b7);\n            tHinge.add(tMesh);\n            eHinge.add(tHinge);\n\n            scene.add(solidGroup);\n        }\n\n        // ==========================================\n        // 2. PYRAMIDE À BASE CARRÉE (Sommet parfait au-dessus du sol)\n        // ==========================================\n        function buildPyramid3D(fp) {\n            solidGroup = new THREE.Group();\n            const s = 2.0;\n            const h = 2.2;\n            const L = Math.sqrt((s/2)*(s/2) + h*h);\n            const alphaClose = Math.atan2(h, s/2);\n            // Angle de rotation par rapport au plan horizontal pour rejoindre le sommet (0 à 180°-alphaClose)\n            const targetAngle = Math.PI - alphaClose;\n            const fa = fp * targetAngle;\n\n            const baseMat = getMaterial(0x0284c7, true);\n            const sideMat = getMaterial(0xf59e0b);\n\n            // Base Carrée au sol Y=0\n            const baseGeo = new THREE.PlaneGeometry(s, s);\n            baseGeo.rotateX(-Math.PI / 2);\n            const baseMesh = new THREE.Mesh(baseGeo, baseMat);\n            addOutline(baseMesh, 0x38bdf8);\n            solidGroup.add(baseMesh);\n\n            // Triangle Nord (charnière z = -s/2, pointe vers -Z) -> rotation.x = +fa (PLIE VERS LE HAUT)\n            const nHinge = new THREE.Group();\n            nHinge.position.set(0, 0, -s/2);\n            nHinge.rotation.x = fa;\n            const nGeo = new THREE.BufferGeometry();\n            nGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                -s/2, 0, 0,\n                 s/2, 0, 0,\n                   0, 0, -L\n            ]), 3));\n            nGeo.computeVertexNormals();\n            const nMesh = new THREE.Mesh(nGeo, sideMat);\n            addOutline(nMesh, 0xfcd34d);\n            nHinge.add(nMesh);\n            solidGroup.add(nHinge);\n\n            // Triangle Sud (charnière z = +s/2, pointe vers +Z) -> rotation.x = -fa (PLIE VERS LE HAUT)\n            const sHinge = new THREE.Group();\n            sHinge.position.set(0, 0, s/2);\n            sHinge.rotation.x = -fa;\n            const sGeo = new THREE.BufferGeometry();\n            sGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                -s/2, 0, 0,\n                 s/2, 0, 0,\n                   0, 0, L\n            ]), 3));\n            sGeo.computeVertexNormals();\n            const sMesh = new THREE.Mesh(sGeo, sideMat);\n            addOutline(sMesh, 0xfcd34d);\n            sHinge.add(sMesh);\n            solidGroup.add(sHinge);\n\n            // Triangle Ouest (charnière x = -s/2, pointe vers -X) -> rotation.z = -fa (PLIE VERS LE HAUT)\n            const wHinge = new THREE.Group();\n            wHinge.position.set(-s/2, 0, 0);\n            wHinge.rotation.z = -fa;\n            const wGeo = new THREE.BufferGeometry();\n            wGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                0, 0, -s/2,\n                0, 0,  s/2,\n               -L, 0,  0\n            ]), 3));\n            wGeo.computeVertexNormals();\n            const wMesh = new THREE.Mesh(wGeo, sideMat);\n            addOutline(wMesh, 0xfcd34d);\n            wHinge.add(wMesh);\n            solidGroup.add(wHinge);\n\n            // Triangle Est (charnière x = +s/2, pointe vers +X) -> rotation.z = +fa (PLIE VERS LE HAUT)\n            const eHinge = new THREE.Group();\n            eHinge.position.set(s/2, 0, 0);\n            eHinge.rotation.z = fa;\n            const eGeo = new THREE.BufferGeometry();\n            eGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                0, 0, -s/2,\n                0, 0,  s/2,\n                L, 0,  0\n            ]), 3));\n            eGeo.computeVertexNormals();\n            const eMesh = new THREE.Mesh(eGeo, sideMat);\n            addOutline(eMesh, 0xfcd34d);\n            eHinge.add(eMesh);\n            solidGroup.add(eHinge);\n\n            scene.add(solidGroup);\n        }\n\n        // ==========================================\n        // 3. PRISME DROIT TRIANGULAIRE\n        // ==========================================\n        function buildPrism3D(fp) {\n            solidGroup = new THREE.Group();\n            const w = 1.8;\n            const h = 2.4;\n            const ht = w * Math.sqrt(3) / 2; // ~1.5588\n            const sa = fp * (Math.PI / 3); // 60 deg\n            const ca = fp * (Math.PI / 2); // 90 deg\n\n            const baseMat = getMaterial(0x0284c7, true);\n            const sideMat = getMaterial(0xf59e0b);\n            const capMat  = getMaterial(0x10b981);\n\n            // Base centrale rectangulaire sur XZ\n            const cGeo = new THREE.PlaneGeometry(w, h);\n            cGeo.rotateX(-Math.PI / 2);\n            const cMesh = new THREE.Mesh(cGeo, baseMat);\n            addOutline(cMesh, 0x38bdf8);\n            solidGroup.add(cMesh);\n\n            // Face Gauche (charnière x = -w/2, pointe vers -X) -> Pliage HAUT => rotation.z = -sa\n            const lHinge = new THREE.Group();\n            lHinge.position.set(-w/2, 0, 0);\n            lHinge.rotation.z = -sa;\n            const lGeo = new THREE.PlaneGeometry(w, h);\n            lGeo.rotateX(-Math.PI / 2);\n            lGeo.translate(-w/2, 0, 0);\n            const lMesh = new THREE.Mesh(lGeo, sideMat);\n            addOutline(lMesh, 0xfcd34d);\n            lHinge.add(lMesh);\n            solidGroup.add(lHinge);\n\n            // Face Droite (charnière x = +w/2, pointe vers +X) -> Pliage HAUT => rotation.z = +sa\n            const rHinge = new THREE.Group();\n            rHinge.position.set(w/2, 0, 0);\n            rHinge.rotation.z = sa;\n            const rGeo = new THREE.PlaneGeometry(w, h);\n            rGeo.rotateX(-Math.PI / 2);\n            rGeo.translate(w/2, 0, 0);\n            const rMesh = new THREE.Mesh(rGeo, sideMat);\n            addOutline(rMesh, 0xfcd34d);\n            rHinge.add(rMesh);\n            solidGroup.add(rHinge);\n\n            // Triangle Nord (charnière z = -h/2, pointe vers -Z) -> Pliage HAUT => rotation.x = +ca\n            const nHinge = new THREE.Group();\n            nHinge.position.set(0, 0, -h/2);\n            nHinge.rotation.x = ca;\n            const nGeo = new THREE.BufferGeometry();\n            nGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                -w/2, 0, 0,\n                 w/2, 0, 0,\n                   0, 0, -ht\n            ]), 3));\n            nGeo.computeVertexNormals();\n            const nMesh = new THREE.Mesh(nGeo, capMat);\n            addOutline(nMesh, 0x6ee7b7);\n            nHinge.add(nMesh);\n            solidGroup.add(nHinge);\n\n            // Triangle Sud (charnière z = +h/2, pointe vers +Z) -> Pliage HAUT => rotation.x = -ca\n            const sHinge = new THREE.Group();\n            sHinge.position.set(0, 0, h/2);\n            sHinge.rotation.x = -ca;\n            const sGeo = new THREE.BufferGeometry();\n            sGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([\n                -w/2, 0, 0,\n                 w/2, 0, 0,\n                   0, 0, ht\n            ]), 3));\n            sGeo.computeVertexNormals();\n            const sMesh = new THREE.Mesh(sGeo, capMat);\n            addOutline(sMesh, 0x6ee7b7);\n            sHinge.add(sMesh);\n            solidGroup.add(sHinge);\n\n            scene.add(solidGroup);\n        }\n\n        // ==========================================\n        // 4. CYLINDRE DE RÉVOLUTION (Disques ajustés)\n        // ==========================================\n        function buildCylinder3D(fp) {\n            solidGroup = new THREE.Group();\n            const R = 1.0;\n            const H = 2.2;\n            const P = 2 * Math.PI * R;\n            const N = 48;\n            const f = fp;\n\n            const sideMat = getMaterial(0xf59e0b);\n            const capMat  = getMaterial(0x0284c7, true);\n\n            const segWidth = P / N;\n            const curAngleTotal = f * 2 * Math.PI;\n\n            const latGroup = new THREE.Group();\n\n            for (let i = 0; i < N; i++) {\n                const segGeo = new THREE.PlaneGeometry(segWidth, H);\n                segGeo.rotateX(-Math.PI / 2);\n\n                const segMesh = new THREE.Mesh(segGeo, sideMat);\n\n                if (f <= 0.001) {\n                    const x = (i - N/2 + 0.5) * segWidth;\n                    segMesh.position.set(x, 0, 0);\n                } else {\n                    const curRadius = R / f;\n                    const angle = (i - N/2 + 0.5) * (curAngleTotal / N);\n                    const x = curRadius * Math.sin(angle);\n                    const z = -curRadius * (1 - Math.cos(angle));\n                    segMesh.position.set(x, 0, z);\n                    segMesh.rotation.y = angle;\n                }\n                latGroup.add(segMesh);\n            }\n\n            if (f > 0.001) {\n                latGroup.children.forEach(mesh => {\n                    mesh.rotation.x = f * (Math.PI / 2);\n                    mesh.position.y = (H / 2) * f;\n                });\n            }\n\n            // Disque Supérieur (Couvercle)\n            const topHinge = new THREE.Group();\n            const curH = f * H;\n            topHinge.position.set(0, curH, f <= 0.001 ? -R : 0);\n            topHinge.rotation.x = f * (Math.PI / 2);\n\n            const circleGeoTop = new THREE.CircleGeometry(R, 32);\n            circleGeoTop.rotateX(-Math.PI / 2);\n            if (f <= 0.001) circleGeoTop.translate(0, 0, -R);\n            const topMesh = new THREE.Mesh(circleGeoTop, capMat);\n            addOutline(topMesh, 0x38bdf8);\n            topHinge.add(topMesh);\n\n            // Disque Inférieur (Base)\n            const botHinge = new THREE.Group();\n            botHinge.position.set(0, 0, f <= 0.001 ? R : 0);\n            botHinge.rotation.x = -f * (Math.PI / 2);\n\n            const circleGeoBot = new THREE.CircleGeometry(R, 32);\n            circleGeoBot.rotateX(-Math.PI / 2);\n            if (f <= 0.001) circleGeoBot.translate(0, 0, R);\n            const botMesh = new THREE.Mesh(circleGeoBot, capMat);\n            addOutline(botMesh, 0x38bdf8);\n            botHinge.add(botMesh);\n\n            solidGroup.add(latGroup);\n            solidGroup.add(topHinge);\n            solidGroup.add(botHinge);\n\n            scene.add(solidGroup);\n        }\n\n        // ==========================================\n        // 5. CÔNE DE RÉVOLUTION\n        // ==========================================\n        function buildCone3D(fp) {\n            solidGroup = new THREE.Group();\n            const R = 1.0;\n            const H = 2.2;\n            const A = Math.sqrt(R*R + H*H); // ~2.4166\n            const N = 48;\n            const f = fp;\n\n            const sideMat = getMaterial(0x7c3aed);\n            const capMat  = getMaterial(0x0284c7, true);\n\n            const targetTheta = 2 * Math.PI * (R / A);\n            const curTheta = f * 2 * Math.PI + (1 - f) * targetTheta;\n            const curHeight = f * H;\n            const curRadius = f * R + (1 - f) * A;\n\n            const sectorGroup = new THREE.Group();\n\n            for (let i = 0; i < N; i++) {\n                const t1 = (i / N) * curTheta - curTheta / 2;\n                const t2 = ((i + 1) / N) * curTheta - curTheta / 2;\n\n                const triGeo = new THREE.BufferGeometry();\n                \n                if (f <= 0.001) {\n                    const v = new Float32Array([\n                        0, 0, 0,\n                        A * Math.sin(t1), 0, A * Math.cos(t1),\n                        A * Math.sin(t2), 0, A * Math.cos(t2)\n                    ]);\n                    triGeo.setAttribute('position', new THREE.BufferAttribute(v, 3));\n                } else {\n                    const v = new Float32Array([\n                        0, curHeight, 0,\n                        curRadius * Math.sin(t1), 0, curRadius * Math.cos(t1),\n                        curRadius * Math.sin(t2), 0, curRadius * Math.cos(t2)\n                    ]);\n                    triGeo.setAttribute('position', new THREE.BufferAttribute(v, 3));\n                }\n                triGeo.computeVertexNormals();\n                const triMesh = new THREE.Mesh(triGeo, sideMat);\n                sectorGroup.add(triMesh);\n            }\n\n            const baseHinge = new THREE.Group();\n            baseHinge.position.set(0, 0, f <= 0.001 ? A : 0);\n            baseHinge.rotation.x = -f * (Math.PI / 2);\n\n            const baseGeo = new THREE.CircleGeometry(R, 32);\n            baseGeo.rotateX(-Math.PI / 2);\n            if (f <= 0.001) baseGeo.translate(0, 0, R);\n            const baseMesh = new THREE.Mesh(baseGeo, capMat);\n            addOutline(baseMesh, 0x38bdf8);\n            baseHinge.add(baseMesh);\n\n            solidGroup.add(sectorGroup);\n            solidGroup.add(baseHinge);\n\n            scene.add(solidGroup);\n        }\n\n        // Initialisation de la simulation 3D au chargement\n        function initApp() {\n            init3D();\n        }\n\n        if (document.readyState === 'loading') {\n            document.addEventListener('DOMContentLoaded', initApp);\n        } else {\n            initApp();\n        }\n    </script>\n</body>\n</html>\n</body>\n</html>\n</body>\n</html>\n</body>\n</html>\n</body>\n</html>\n\n</body>\n</html>";

